{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://goobers.dev/schemas/instance.schema.json",
  "title": "Instance",
  "description": "instance.yaml — the deployment-owned provisioning file `goobers init` writes first and the first file an operator edits. It declares which repositories this instance connects to, WHERE each credential is read from (never the value itself, CFG-009/SEC-010), and the instance-wide runner claims, run conditions, and telemetry every gaggle inherits. Gaggle/goober/workflow definitions are config-as-code reconciled from the workflow source; this file is provisioning, so it is loaded strictly — an unknown field is an error, never a silently ignored setting.",
  "type": "object",
  "additionalProperties": false,
  "required": ["apiVersion", "kind", "repos"],
  "allOf": [
    {
      "$comment": "The other half of the strict-load contract (#4217): a runners: inventory is schema revision 2, so declaring one without saying so is refused here exactly as the loader refuses it. Without this, editor validation would accept a file the daemon rejects.",
      "if": { "required": ["runners"] },
      "then": {
        "required": ["schemaVersion"],
        "properties": { "schemaVersion": { "const": 2 } }
      }
    }
  ],
  "properties": {
    "placement": {
      "type": "object",
      "additionalProperties": false,
      "description": "Instance workflow placement policy. Omitted keeps local execution compatible; hosted instances should explicitly deny self execution.",
      "properties": {
        "selfExecution": { "type": "string", "enum": ["allow", "deny"], "default": "allow", "description": "allow permits local workflow work (the default); deny refuses every self placement, including agentic reviewer gates." }
      }
    },
    "cost": {
      "type": "object",
      "description": "Instance default for external cost publication; local usage accounting remains active.",
      "additionalProperties": false,
      "properties": {
