           "additionalProperties": false,
           "properties": {
             "os": {
               "description": "Required operating system for the reviewer — a validated enum (product spellings, not GOOS). Unset means no OS requirement; placement policy prefers, and will wait bounded for, a Linux-class runner when the inventory has one.",
               "type": "string",
               "enum": ["linux", "windows", "macOS"]
             },
             "cpu": {
               "description": "Minimum CPU for the reviewer as a Kubernetes quantity string (e.g. \"2000m\"), verbatim. Required whenever runsOn is declared on a gate (WF023). Minimums become pod resource requests in distributed mode; limits come from the matched runner's ceiling. Advisory on local modes.",
               "type": "string",
               "minLength": 1
             },
             "memory": {
               "description": "Minimum memory for the reviewer as a Kubernetes quantity string (e.g. \"4Gi\"), verbatim. Required whenever runsOn is declared on a gate (WF023).",
               "type": "string",
               "minLength": 1
             },
             "disk": {
               "description": "Minimum disk for the reviewer as a Kubernetes quantity string (e.g. \"20Gi\"), verbatim.",
               "type": "string",
               "minLength": 1
             },
             "capabilities": {
               "description": "Open toolchain tag set the reviewer's runner must provide (internal/runnercap grammar, exact set membership, no ranges); unions with the gaggle floor and the derived harness tag. os=* tokens are rejected (CAP004): runsOn.os is the only platform vocabulary in a 3.0 document. maxItems bounds CRD CEL validation cost (#3168).",
               "type": "array",
               "maxItems": 32,
               "items": { "type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9._@=+-]*$" }
             },
             "restrictions": {
               "description": "Isolation effects the reviewer's runner must ENFORCE, from the closed v1 effect list (Goobernetes decision D7). Unknown tokens are rejected with a suggestion (CAP005). maxItems bounds CRD CEL validation cost (#3168).",
               "type": "array",
               "maxItems": 8,
               "items": {
                 "type": "string",
                 "enum": ["network:none", "network:allowlist", "fs:readonly-except-workspace", "tmp:ephemeral", "env:default-deny"]
               }
             }
           }
         },
         "branches": {
           "type": "object",
           "description": "Outcome-to-next-state mapping. The pass key is the success branch; escalate may route forced escalation.",
           "minProperties": 1,
           "additionalProperties": { "type": "string" }
         }
       },
       "allOf": [
         {
           "if": { "properties": { "evaluator": { "const": "automated" } } },
           "then": { "required": ["automated"], "not": { "anyOf": [{ "required": ["agentic"] }, { "required": ["human"] }] } }

