      "type": "string",
      "pattern": "^[A-Za-z_][A-Za-z0-9_]*$",
      "description": "Name of an environment variable holding the token, read from the DAEMON process — so it must be exported before `goobers up`, not inside a stage. A name that stages can also see (through runner.envPassthrough or the built-in allowlist) is refused for secrets that must never reach a stage.",
      "examples": ["GOOBERS_GITHUB_TOKEN"]
    },
    "file": { "type": "string", "minLength": 1, "description": "Path to a file whose entire contents are the token." },
    "keychain": { "type": "string", "minLength": 1, "description": "Service name of a generic-password item in the macOS login keychain." },
    "store": {
      "type": "string",
      "minLength": 1,
      "description": "Secret in a declared secret store, written as `<storeName>/<secretName>`. The store name must match a secretStores entry; the secret name is interpreted by that store's resolver.",
      "examples": ["prod-kv/github-token"]
    },
    "githubCLI": {
      "description": "One explicitly selected GitHub CLI account. The daemon resolves and verifies this account at startup, caches only the token in memory, and never follows later ambient account switches.",
