    },
    "defaultStageTimeout": {
      "$ref": "instance-repository-execution.schema.json#/properties/defaultStageTimeout",
      "description": "Deadline for this repository's deterministic stages that declare no timeoutSeconds. It overrides both the large-repo preset and the instance-wide runner.defaultStageTimeout.",
      "examples": ["4h"]
