        "properties": {
          "provider": { "const": "github" },
          "token": { "not": { "required": ["githubCLI"] } }
        }
      }
    }
  ]
},
"repoAuth": {
  "description": "Credential SOURCE selector for one repository — never credential material. Kind values are provider-specific: github accepts pat, github-app and github-app-token; ado accepts pat, azure-cli, workload-identity, and managed-identity; gitea accepts no auth block at all (static token only). Fields belonging to another provider's kinds are rejected at load rather than ignored.",
  "type": "object",
  "additionalProperties": false,
  "required": ["kind"],
  "properties": {
    "kind": {
      "type": "string",
      "enum": ["pat", "github-app", "github-app-token", "azure-cli", "workload-identity", "managed-identity"],
      "description": "Identity mechanism: `pat` reads the static token ref; `github-app-token` reads an externally minted installation token and requires its App slug; `github-app` mints short-lived installation tokens (GitHub); `azure-cli` borrows the current local az login, `workload-identity` uses federated Azure workload identity, and `managed-identity` uses an Azure managed identity (all Azure DevOps). Only `pat` and `github-app-token` accept a token ref on the same repository."
    },
    "tenant": { "type": "string", "minLength": 1, "description": "Pins Azure CLI authentication to one tenant. Azure DevOps only." },
    "clientId": { "type": "string", "minLength": 1, "description": "Selects a user-assigned identity. Valid with kind `workload-identity` or `managed-identity`; for workload identity it overrides the ambient AZURE_CLIENT_ID while reusing the projected federated token." },
    "appId": {
      "$ref": "#/$defs/githubId",
      "description": "GitHub App identifier for kind `github-app`: the numeric App ID or the App's client ID string — GitHub accepts either as the App JWT issuer."
    },
    "installationId": {
      "$ref": "#/$defs/githubId",
      "description": "Numeric ID of the App's installation on this repository's owner, for kind `github-app`. It must be the installation ID, not the App ID."
    },
    "privateKey": {
      "description": "Where the App's PEM-encoded private key is read from, for kind `github-app`. The key only ever signs short-lived App JWTs in this process; stages receive minted installation tokens, never the key, so an env name that stages can see is refused.",
      "$ref": "#/$defs/tokenRef"
    },
    "slug": {
      "type": "string",
      "description": "The App's URL-safe handle (the part before `[bot]` in its GitHub login), for `github-app` or `github-app-token`. Required for `github-app-token`: the external issuer must bind this declared identity to the supplied token. Installation tokens cannot call GET /user, so trusted-comment checks use this declared identity (#3343)."
    }
  },
  "allOf": [
    {
      "if": { "properties": { "kind": { "const": "github-app" } }, "required": ["kind"] },
      "then": { "required": ["appId", "installationId", "privateKey"] }
    },
    {
      "if": { "properties": { "kind": { "const": "github-app-token" } }, "required": ["kind"] },
      "then": {
        "required": ["slug"],
        "properties": {
          "slug": { "pattern": "^[A-Za-z0-9][A-Za-z0-9-]{0,38}$" },
          "appId": false, "installationId": false, "privateKey": false,
          "tenant": false, "clientId": false
        }
      }
    }
  ]
},
"repoPolicy": {
  "description": "Declared expectations about a repository's live branch protection, checked by `goobers doctor --repo`. Deployment-owned rules, which is why they live here rather than in workflow config. Nothing here changes the repository; it only reports drift.",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "branch": { "type": "string", "minLength": 1, "description": "Branch these expectations apply to. Empty defaults to main." },
    "requiredMergeMethod": {
      "type": "string",
      "enum": ["merge", "squash", "rebase"],
      "description": "The one merge method the repository must allow exclusively. Set it when a squash-only ruleset and a merge-commit setting can disagree; empty imposes no requirement."
    },
    "mergeQueueRequired": { "type": "boolean", "description": "Requires the branch to use the provider's native merge queue rather than accepting a direct-merge path." },
    "requiredStatusChecks": {
      "description": "Check contexts the branch's live rules must require. Entries are matched by exact context name, so a renamed CI job silently stops being required — that rename is what this list catches.",
      "type": "array",
      "items": { "type": "string", "minLength": 1 }
    }
  }
},
"credentialGrant": {
  "description": "One credential source for exactly one capability OR one named BYO MCP credential. Set exactly one of capability and mcp; each may be sourced only once per instance per harness scope — a (capability, mcp, harness) triple may be granted at most once.",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "capability": {
      "type": "string",
      "enum": [
        "repo:read",
        "repo:push",
        "configrepo:write",
        "github:issues:read",
        "github:issues:write",
        "github:milestones:write",
        "github:issues:approve",
        "provider:pr:write",
        "github:pr:read",
        "github:pr:write",
        "github:pr:review",
        "provider:ci:cancel",
        "github:branch:delete",
        "github:pr:merge",
        "contents:read",
        "github:code-scanning:read",
        "github:dependabot-alerts:read",
        "ado:code:read",
        "ado:pr:comment",
        "ado:pr:write",
        "ado:pr:status",
        "ado:pr:complete",
        "ado:work-items:write",
        "ado:packaging:read",
        "telemetry:read",
        "journal:read",
        "agent:model"
      ],
      "description": "Canonical capability this token backs, overriding the repository-token default for that capability alone. `agent:model` is the agent harness credential; github:pr:review needs a DIFFERENT identity from the one authoring pull requests, because an author cannot approve its own. Runner-owned capabilities are not grantable here — configrepo:read comes from workflowSource.token."
