       "additionalProperties": false,
       "required": ["provider", "owner", "name"],
       "properties": {
         "provider": {
           "type": "string",
           "enum": ["github", "ado", "gitea"],
           "description": "Backing system for this repository. It selects both the API surface and which auth kinds are accepted."
         },
         "baseUrl": {
           "type": "string",
           "format": "uri",
           "description": "Forge root URL (e.g. https://gitea.example.com). Required for provider `gitea`, which has no fixed host; omitted for ado. Rejected for provider `github`: GitHub Enterprise Server is unsupported, so a github repository always means github.com."
         },
         "owner": {
           "type": "string",
           "minLength": 1,
           "description": "GitHub organization or user, Gitea owner, or Azure DevOps ORGANIZATION (the first segment of dev.azure.com/<organization>)."
         },
         "project": {
           "type": "string",
           "minLength": 1,
           "description": "Azure DevOps PROJECT — the middle segment of the three-part organization/project/repository identity. Required for provider `ado`; rejected for github and gitea, where it has no meaning."
         },
         "name": { "type": "string", "minLength": 1, "description": "Repository name — the last segment of the identity." },
         "token": {
           "description": "Where this repository's credential is read from. Required for PAT auth and externally minted github-app-token auth. It must be ABSENT for an auth kind that mints or borrows an identity (github-app, azure-cli, workload-identity, managed-identity): exactly one identity mechanism per repository, since a token alongside a minted one could only act as a silent fallback.",
           "$ref": "#/$defs/tokenRef"
         },
         "auth": {
           "description": "Non-default credential source for this repository. Omitted means PAT auth with token configured — byte-identical to an instance that predates this block.",
           "$ref": "#/$defs/repoAuth"
         },
         "policy": {
           "description": "This repository's declared forge-conformance manifest: the live settings `goobers doctor --repo` diffs against. GitHub-only. Omitted declares no expectation and changes nothing.",
           "$ref": "#/$defs/repoPolicy"
         },
         "largeRepo": {
           "$ref": "instance-repository-execution.schema.json#/properties/largeRepo",
           "description": "Enables the monolith-safe execution preset (pinned serial workspace, 4h stage timeout, path-length preflight, retention exemption, narrowed mirror refresh). The preset supplies DEFAULTS only — every explicit setting below overrides it."
         },
         "workspace": {
           "$ref": "instance-repository-execution.schema.json#/properties/workspace",
           "description": "How this repository is materialized for local runs. Pinned mode is deliberately non-hermetic: ignored and untracked build state may persist between runs, so the repository's .gitignore hygiene becomes load-bearing for clean run-branch diffs."
         },
         "pathLength": {
           "$ref": "instance-repository-execution.schema.json#/properties/pathLength",
           "description": "Checkout path-length preflight for this repository. Declaring the block enables it on every host, not just Windows; set disabled to opt out."
         },
         "defaultStageTimeout": {
           "$ref": "instance-repository-execution.schema.json#/properties/defaultStageTimeout",
           "description": "Deadline for this repository's deterministic stages that declare no timeoutSeconds. It overrides both the large-repo preset and the instance-wide runner.defaultStageTimeout.",
           "examples": ["4h"]
         },
         "runControls": {
           "$ref": "instance-repository-execution.schema.json#/properties/runControls",
           "description": "Watchdog budgets for runs targeting this repository, overriding runConditions. Gaggle and workflow runControls remain more specific."
         }
       },
       "allOf": [
         {
           "if": { "properties": { "provider": { "const": "ado" } }, "required": ["provider"] },
           "then": { "required": ["project"] }
         },
         {
           "if": { "properties": { "provider": { "const": "gitea" } }, "required": ["provider"] },
           "then": { "required": ["baseUrl"] }
         },
         {
           "if": { "properties": { "provider": { "const": "github" } }, "required": ["provider"] },
           "then": { "properties": { "baseUrl": false } }
         },
         {
           "if": {
             "required": ["auth"],
             "properties": { "auth": { "required": ["kind"], "properties": { "kind": { "const": "github-app-token", "description": "Selects an externally minted GitHub App installation token." } } } }
           },
           "then": {
             "required": ["token"],
             "properties": {
               "provider": { "const": "github" },
               "token": { "not": { "required": ["githubCLI"] } }
             }
           }
         }
       ]
     },
     "repoAuth": {
       "description": "Credential SOURCE selector for one repository — never credential material. Kind values are provider-specific: github accepts pat, github-app and github-app-token; ado accepts pat, azure-cli, workload-identity, and managed-identity; gitea accepts no auth block at all (static token only). Fields belonging to another provider's kinds are rejected at load rather than ignored.",
       "type": "object",
       "additionalProperties": false,
       "required": ["kind"],
       "properties": {
         "kind": {
           "type": "string",
           "enum": ["pat", "github-app", "github-app-token", "azure-cli", "workload-identity", "managed-identity"],
           "description": "Identity mechanism: `pat` reads the static token ref; `github-app-token` reads an externally minted installation token and requires its App slug; `github-app` mints short-lived installation tokens (GitHub); `azure-cli` borrows the current local az login, `workload-identity` uses federated Azure workload identity, and `managed-identity` uses an Azure managed identity (all Azure DevOps). Only `pat` and `github-app-token` accept a token ref on the same repository."
         },
         "tenant": { "type": "string", "minLength": 1, "description": "Pins Azure CLI authentication to one tenant. Azure DevOps only." },
         "clientId": { "type": "string", "minLength": 1, "description": "Selects a user-assigned identity. Valid with kind `workload-identity` or `managed-identity`; for workload identity it overrides the ambient AZURE_CLIENT_ID while reusing the projected federated token." },
         "appId": {
           "$ref": "#/$defs/githubId",
           "description": "GitHub App identifier for kind `github-app`: the numeric App ID or the App's client ID string — GitHub accepts either as the App JWT issuer."
         },
         "installationId": {
           "$ref": "#/$defs/githubId",
           "description": "Numeric ID of the App's installation on this repository's owner, for kind `github-app`. It must be the installation ID, not the App ID."
         },
         "privateKey": {
           "description": "Where the App's PEM-encoded private key is read from, for kind `github-app`. The key only ever signs short-lived App JWTs in this process; stages receive minted installation tokens, never the key, so an env name that stages can see is refused.",
           "$ref": "#/$defs/tokenRef"
         },
         "slug": {
           "type": "string",
           "description": "The App's URL-safe handle (the part before `[bot]` in its GitHub login), for `github-app` or `github-app-token`. Required for `github-app-token`: the external issuer must bind this declared identity to the supplied token. Installation tokens cannot call GET /user, so trusted-comment checks use this declared identity (#3343)."
         }
       },
       "allOf": [
         {
           "if": { "properties": { "kind": { "const": "github-app" } }, "required": ["kind"] },
           "then": { "required": ["appId", "installationId", "privateKey"] }
         },
         {
           "if": { "properties": { "kind": { "const": "github-app-token" } }, "required": ["kind"] },
           "then": {
             "required": ["slug"],
             "properties": {
               "slug": { "pattern": "^[A-Za-z0-9][A-Za-z0-9-]{0,38}$" },
               "appId": false, "installationId": false, "privateKey": false,
               "tenant": false, "clientId": false
             }
           }
         }
       ]
     },
     "repoPolicy": {
       "description": "Declared expectations about a repository's live branch protection, checked by `goobers doctor --repo`. Deployment-owned rules, which is why they live here rather than in workflow config. Nothing here changes the repository; it only reports drift.",
       "type": "object",
       "additionalProperties": false,
       "properties": {
         "branch": { "type": "string", "minLength": 1, "description": "Branch these expectations apply to. Empty defaults to main." },
         "requiredMergeMethod": {
           "type": "string",
           "enum": ["merge", "squash", "rebase"],
           "description": "The one merge method the repository must allow exclusively. Set it when a squash-only ruleset and a merge-commit setting can disagree; empty imposes no requirement."
         },
         "mergeQueueRequired": { "type": "boolean", "description": "Requires the branch to use the provider's native merge queue rather than accepting a direct-merge path." },
         "requiredStatusChecks": {
           "description": "Check contexts the branch's live rules must require. Entries are matched by exact context name, so a renamed CI job silently stops being required — that rename is what this list catches.",
           "type": "array",
           "items": { "type": "string", "minLength": 1 }
         }
       }
     },
     "credentialGrant": {
       "description": "One credential source for exactly one capability OR one named BYO MCP credential. Set exactly one of capability and mcp; each may be sourced only once per instance per harness scope — a (capability, mcp, harness) triple may be granted at most once.",
       "type": "object",
       "additionalProperties": false,
       "properties": {
         "capability": {
           "type": "string",
           "enum": [
             "repo:read",
             "repo:push",
             "configrepo:write",
             "github:issues:read",
             "github:issues:write",
             "github:milestones:write",
             "github:issues:approve",
             "provider:pr:write",
             "github:pr:read",
             "github:pr:write",
             "github:pr:review",
             "provider:ci:cancel",
             "github:branch:delete",
             "github:pr:merge",
             "contents:read",
             "github:code-scanning:read",
             "github:dependabot-alerts:read",
             "ado:code:read",
             "ado:pr:comment",
             "ado:pr:write",
             "ado:pr:status",
             "ado:pr:complete",
             "ado:work-items:write",
             "ado:packaging:read",
             "telemetry:read",
             "journal:read",
             "agent:model"
           ],
           "description": "Canonical capability this token backs, overriding the repository-token default for that capability alone. `agent:model` is the agent harness credential; github:pr:review needs a DIFFERENT identity from the one authoring pull requests, because an author cannot approve its own. Runner-owned capabilities are not grantable here — configrepo:read comes from workflowSource.token."
         },
         "mcp": {
           "type": "string",
           "pattern": "^[a-z0-9]([-a-z0-9]*[a-z0-9])?$",
           "description": "Name of a bring-your-own MCP credential. It is NOT a stage capability: it is reachable only by goobers whose MCP server declarations reference this name."
         },
         "harness": {
           "type": "string",
           "enum": ["copilot", "claude-code", "codex"],
           "description": "Scopes this grant to one agent harness so an instance can run goobers on more than one harness with each getting its own non-interchangeable secret — e.g. copilot's COPILOT_GITHUB_TOKEN, claude-code's ANTHROPIC_API_KEY or CLAUDE_CODE_OAUTH_TOKEN, codex's CODEX_API_KEY. A goober running that harness resolves this grant over an unscoped one sourcing the same capability/mcp; a goober on any other harness never resolves it. Omitted, the grant backs every harness (the pre-existing, single-harness-instance behavior)."
         },
         "token": {
           "description": "Where this credential is read from — exactly one source, never an inline value.",
           "$ref": "#/$defs/tokenRef"
         },
         "githubApp": {
           "description": "Short-lived GitHub App installation-token source for a Copilot-scoped agent:model grant. The token is always requested for exactly one repository with only copilot_requests:write and metadata:read; stages never receive the private key.",
           "type": "object",
           "additionalProperties": false,
           "required": ["name", "appId", "installationId", "repository", "repositoryId", "privateKey"],
           "properties": {
             "name": {
               "type": "string",
               "pattern": "^[a-z0-9]([-a-z0-9]*[a-z0-9])?$",
               "description": "Stable identity name used in diagnostics and to distinguish the request/throttling boundary assigned to this instance or cluster."
             },
             "appId": { "$ref": "#/$defs/githubId", "description": "GitHub App identifier used as the App JWT issuer." },
             "installationId": { "$ref": "#/$defs/githubId", "description": "Numeric installation ID on the repository owner." },
             "repository": {
               "type": "string",
               "pattern": "^[^/\\s]+/[^/\\s]+$",
               "description": "Exact owner/name whose installation token is requested.",
               "examples": ["example-org/example-repo"]
             },
             "repositoryId": { "$ref": "#/$defs/githubId", "description": "Positive immutable numeric ID used to restrict the installation-token request without owner/name ambiguity." },
             "privateKey": {
               "description": "Reference to the App's PEM private key. Inline key material is never accepted.",
               "$ref": "#/$defs/tokenRef"
             }
           }
         }
       },

