{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://goobers.dev/schemas/manifest.schema.json",
  "title": "Manifest",
  "description": "Top-level config-as-code desired state for an instance (CFG-002).",
  "type": "object",
  "additionalProperties": false,
  "required": ["apiVersion", "kind", "metadata", "spec"],
  "properties": {
    "apiVersion": { "const": "goobers.dev/v1alpha1", "description": "API version of this instance manifest." },
    "kind": { "const": "Manifest", "description": "Definition kind; always Manifest." },
    "metadata": { "$ref": "#/$defs/metadata", "description": "Identity and optional labels or annotations for this manifest." },
    "spec": {
      "type": "object",
      "description": "The instance identity, reusable external connections, and active gaggles.",
      "additionalProperties": false,
      "required": ["instance"],
      "properties": {
        "instance": {
          "type": "object",
          "description": "Identity of the deployed Goobers instance configured by this manifest.",
          "additionalProperties": false,
          "required": ["name", "environment"],
          "properties": {
            "name": { "type": "string", "minLength": 1, "description": "Name of this Goobers instance." },
            "environment": { "type": "string", "enum": ["dev", "staging", "prod"], "description": "Deployment environment represented by this independently deployed instance." }
          }
        },
        "connections": {
          "type": "array",
          "description": "Named reusable links to external systems that gaggles may reference by connectionRef. Accepted but not yet used to source credentials; credentials come from instance.yaml repos[], credentials[] and secretStores.",
          "items": { "$ref": "#/$defs/connection" }
        },
        "gaggles": {
          "type": "array",
          "description": "Names of gaggle definitions included in this instance's desired state.",
          "items": { "type": "string", "minLength": 1 }
        }
      }
    }
  },
  "$defs": {
    "metadata": {
      "description": "Deliberately left open (no additionalProperties:false) unlike the rest of this schema: k8s-style metadata objects tolerate forward-compatible extra fields (e.g. a future resourceVersion) by convention (#125).",
      "type": "object",
      "required": ["name"],
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1,
          "maxLength": 253,
          "pattern": "^[a-z0-9]([-a-z0-9]*[a-z0-9])?$",
          "description": "DNS-label-compatible manifest name."
        },
        "labels": { "type": "object", "description": "String labels used to organize this manifest.", "additionalProperties": { "type": "string" } },
        "annotations": { "type": "object", "description": "Non-identifying string metadata attached to this manifest.", "additionalProperties": { "type": "string" } }
      }
    },
    "connection": {
      "type": "object",
      "additionalProperties": false,
      "required": ["name", "type", "provider", "secretRef"],
      "properties": {
        "name": { "type": "string", "minLength": 1, "description": "Name used by gaggles and goobers to reference this connection." },
        "type": { "type": "string", "enum": ["repo", "backlog", "telemetry", "identity", "harness"], "description": "Category of external system this connection links to." },
        "provider": { "type": "string", "minLength": 1, "description": "Backing vendor or service, such as github, ado, azure-adx, or entra." },
        "secretRef": { "$ref": "#/$defs/secretRef", "description": "Name of the secret for this connection. Required but not yet read at runtime: credentials come from instance.yaml repos[] and credentials[], and Key Vault secrets are read through instance.yaml secretStores. Connection-level credentials are planned (docs/design/provider-access-layer.md)." },
        "endpoint": { "type": "string", "description": "Optional service endpoint or host override." }
      }
    },
    "secretRef": {
      "type": "object",
      "additionalProperties": false,
      "required": ["name"],
      "properties": {
        "name": { "type": "string", "minLength": 1, "description": "Name of the referenced secret." },
        "key": { "type": "string", "description": "Optional field selected from the referenced secret." },
        "keyVault": { "type": "string", "description": "Optional Key Vault containing the secret. Not read at runtime; declare Key Vaults in instance.yaml secretStores." }
      }
    }
  }
}

