// All returns every canonical capability, in declaration order.
func All() []Capability {
	return []Capability{
		RepoRead, RepoPush, ConfigRepoRead, ConfigRepoWrite,
		GitHubIssuesRead, GitHubIssuesWrite, GitHubMilestonesWrite, GitHubIssuesApprove, ProviderPRWrite, GitHubPRRead, GitHubPRWrite, GitHubPRReview, ProviderCICancel, GitHubBranchDelete, GitHubPRMerge, ContentsRead,
		GitHubCodeScanningRead, GitHubDependabotAlertsRead,
		ADOCodeRead, ADOPRComment, ADOPRWrite, ADOPRStatus, ADOPRComplete, ADOWorkItemsWrite, ADOPackagingRead,
		TelemetryRead, JournalRead, AgentModel,
	}
}

// Known reports whether s is a canonical capability string.
func Known(s string) bool {
	for _, c := range All() {
		if string(c) == s {
			return true
		}
	}
	return false
}

// StageDeclarable reports whether s is a canonical capability that workflow
// tasks and goobers may declare. Runner-owned capabilities stay in the same
// canonical registry but are admitted only by their dedicated runner consumer.
func StageDeclarable(s string) bool {
	return Known(s) && s != string(ConfigRepoRead)
}

// Suggest returns the closest canonical capability for a likely typo.
func Suggest(s string) (Capability, bool) {
	if Known(s) {
		return "", false
	}
	bestDistance := -1
	var best Capability
	for _, candidate := range All() {
		distance := textsuggest.Distance(s, string(candidate))
		if bestDistance == -1 || distance < bestDistance {
			bestDistance = distance
			best = candidate
		}
	}
	if bestDistance > 2 {
		return "", false
	}
	return best, true
}

